from pathlib import Path
import json, sqlite3, sys
HOME=Path.home()
CID='MANUAL-SCOUT-HENGELTJES-20260924'
OLD=['DEV-PRED-HENGELTJE-AUTOBUILD-20260930-E001','DEV-PRED-HENGELTJE-DIAG-20261001-E002']
label=sys.argv[1] if len(sys.argv)>1 else 'snapshot'
print('HENGELTJE_RECOVERY_PHASE='+label)
for tid in OLD:
    p=HOME/'.local/state/prediction-command-bus/tasks'/f'{tid}.json'
    if not p.is_file():
        print(f'BUS_STATE {tid}=ABSENT')
        continue
    try: x=json.loads(p.read_text())
    except Exception as exc:
        print(f'BUS_STATE {tid}=UNREADABLE:{type(exc).__name__}')
        continue
    print(f"BUS_STATE {tid} status={x.get('status')} reason={x.get('reason')} route={x.get('route_source')} http={x.get('http_status')}")
for tid in OLD:
    roots=[HOME/'.local/state/prediction-project-executor', HOME/'.local/share/prediction-project-executor/worktrees']
    hits=[]
    for root in roots:
        if root.exists():
            for p in root.rglob('*'):
                if tid in p.name or tid in str(p): hits.append(str(p))
    print(f'EXEC_STATE {tid} hits={len(hits)}')
prod=HOME/'prediction_research_prod'/'knowledge'/'codex_runtime'
cs=prod/'candidate_states'
hits=[]
if cs.exists():
    for p in cs.glob('*.json'):
        try:x=json.loads(p.read_text())
        except Exception:continue
        if x.get('candidate_id')==CID:hits.append((p.stat().st_mtime,p,x))
if not hits:
    print('HENGELTJE_OVERLAY=ABSENT')
else:
    _,p,x=max(hits)
    print('HENGELTJE_OVERLAY='+str(p))
    print('HENGELTJE_QUEUE_STATUS='+str(x.get('queue_status')))
    print('HENGELTJE_BUILD_HANDOFF='+str(bool(x.get('build_handoff'))))
    print('HENGELTJE_RUNTIME_HEALTH='+str(x.get('runtime_health')))
    print('HENGELTJE_PROSPECTIVE='+str(x.get('prospective_outcome') or x.get('prospective_status')))
try:
    dbp=prod/'runtime.sqlite'
    db=sqlite3.connect(f'file:{dbp}?mode=ro',uri=True)
    rows=db.execute('select id,body,status,attempt from tasks order by rowid').fetchall()
    db.close()
except Exception as exc:
    print('RUNTIME_DB='+type(exc).__name__)
else:
    rows2=[]
    for tid,body,status,attempt in rows:
        try:b=json.loads(body)
        except Exception:continue
        if b.get('candidate_id')==CID: rows2.append((tid,b,status,attempt))
    print('HENGELTJE_TASK_COUNT='+str(len(rows2)))
    for tid,b,status,attempt in rows2[-12:]:
        print('HENGELTJE_TASK='+str(tid)+' status='+str(status)+' attempt='+str(attempt)+' class='+str(b.get('task_class')))
print('SAFETY live_trading=false paid_actions=false wallet_actions=false remote_push=false')
